package com.tekwatt.support.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="support_tickets") public class SupportTicket{
@Id private UUID id;@Column(nullable=false,unique=true,length=30)private String ticketNumber;@Column(nullable=false)private UUID tenantId;private UUID requesterId;@Column(nullable=false,length=120)private String requesterName;@Column(nullable=false,length=190)private String requesterEmail;@Column(nullable=false,length=200)private String subject;@Column(nullable=false,columnDefinition="TEXT")private String description;@Column(nullable=false,length=50)private String category;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TicketPriority priority;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private TicketStatus status;private UUID assigneeId;@Column(length=120)private String assigneeName;private UUID stationId;private UUID sessionId;private Instant slaDueAt;private Instant firstResponseAt;private Instant resolvedAt;private Instant closedAt;@Column(nullable=false,updatable=false)private Instant createdAt;@Column(nullable=false)private Instant updatedAt;@Version private long version;
protected SupportTicket(){}public SupportTicket(UUID tenantId,UUID requesterId,String requesterName,String requesterEmail,String subject,String description,String category,TicketPriority priority,UUID stationId,UUID sessionId){id=UUID.randomUUID();ticketNumber="TW-"+Instant.now().toEpochMilli()+"-"+id.toString().substring(0,4).toUpperCase();this.tenantId=tenantId;this.requesterId=requesterId;this.requesterName=requesterName;this.requesterEmail=requesterEmail;this.subject=subject;this.description=description;this.category=category;this.priority=priority;status=TicketStatus.OPEN;this.stationId=stationId;this.sessionId=sessionId;createdAt=Instant.now();updatedAt=createdAt;slaDueAt=createdAt.plusSeconds(slaHours(priority)*3600L);}private static int slaHours(TicketPriority p){return switch(p){case URGENT->2;case HIGH->8;case MEDIUM->24;case LOW->72;};}public void assign(UUID id,String name){assigneeId=id;assigneeName=name;if(status==TicketStatus.OPEN)status=TicketStatus.ASSIGNED;touch();}public void priority(TicketPriority v){priority=v;slaDueAt=createdAt.plusSeconds(slaHours(v)*3600L);touch();}public void status(TicketStatus v){status=v;Instant n=Instant.now();if(v==TicketStatus.IN_PROGRESS&&firstResponseAt==null)firstResponseAt=n;if(v==TicketStatus.RESOLVED)resolvedAt=n;if(v==TicketStatus.CLOSED)closedAt=n;if(v==TicketStatus.OPEN){resolvedAt=null;closedAt=null;}touch();}public void touch(){updatedAt=Instant.now();}
public UUID getId(){return id;}public String getTicketNumber(){return ticketNumber;}public UUID getTenantId(){return tenantId;}public UUID getRequesterId(){return requesterId;}public String getRequesterName(){return requesterName;}public String getRequesterEmail(){return requesterEmail;}public String getSubject(){return subject;}public String getDescription(){return description;}public String getCategory(){return category;}public TicketPriority getPriority(){return priority;}public TicketStatus getStatus(){return status;}public UUID getAssigneeId(){return assigneeId;}public String getAssigneeName(){return assigneeName;}public UUID getStationId(){return stationId;}public UUID getSessionId(){return sessionId;}public Instant getSlaDueAt(){return slaDueAt;}public Instant getFirstResponseAt(){return firstResponseAt;}public Instant getResolvedAt(){return resolvedAt;}public Instant getClosedAt(){return closedAt;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}
